<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2048</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    html, body {
      height: 100%;
      background: #121216;
      color: #e8e8ee;
      font-family: system-ui, -apple-system, Segoe UI, sans-serif;
    }
    body {
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .wrap {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 18px;
    }
    h1 {
      font-size: 42px;
      letter-spacing: 4px;
      font-weight: 800;
      color: #f4f0e6;
    }
    .bar {
      width: 420px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    .scorebox {
      background: #1e1e26;
      border: 1px solid #2e2e38;
      border-radius: 10px;
      padding: 10px 18px;
      min-width: 120px;
      text-align: center;
    }
    .scorebox label {
      display: block;
      font-size: 11px;
      letter-spacing: 1.5px;
      text-transform: uppercase;
      color: #8a8a98;
      margin-bottom: 2px;
    }
    #score {
      font-size: 28px;
      font-weight: 700;
      color: #ffd56a;
    }
    #reset {
      background: #e07a3d;
      color: #1a120c;
      border: none;
      border-radius: 10px;
      padding: 12px 20px;
      font-size: 15px;
      font-weight: 700;
      cursor: pointer;
    }
    #reset:hover { background: #f08a4d; }
    #board {
      width: 420px;
      height: 420px;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      grid-template-rows: repeat(4, 1fr);
      gap: 12px;
      padding: 12px;
      background: #0c0c10;
      border: 1px solid #2a2a34;
      border-radius: 14px;
    }
    .tile {
      display: flex;
      align-items: center;
      justify-content: center;
      border-radius: 8px;
      font-weight: 800;
      background: #22222a;
      color: #f5f0e8;
      user-select: none;
    }
    .tile.v0 { background: #1a1a22; color: transparent; }
    .tile.v2 { background: #3a3a44; color: #eee; font-size: 36px; }
    .tile.v4 { background: #4a4638; color: #f3ead4; font-size: 36px; }
    .tile.v8 { background: #c17a3a; font-size: 36px; }
    .tile.v16 { background: #d45c2e; font-size: 34px; }
    .tile.v32 { background: #e04a32; font-size: 34px; }
    .tile.v64 { background: #e83228; font-size: 34px; }
    .tile.v128 { background: #c9a227; font-size: 30px; }
    .tile.v256 { background: #d4aa1c; font-size: 30px; }
    .tile.v512 { background: #e0b410; font-size: 30px; }
    .tile.v1024 { background: #edc000; color: #1a1408; font-size: 24px; }
    .tile.v2048 { background: #ffd54a; color: #1a1408; font-size: 24px; }
    .tile.vbig { background: #2a1a3a; color: #e8d4ff; font-size: 20px; }
  </style>
</head>
<body>
  <div class="wrap">
    <h1>2048</h1>
    <div class="bar">
      <div class="scorebox">
        <label>Score</label>
        <div id="score">0</div>
      </div>
      <button id="reset" type="button">New Game</button>
    </div>
    <div id="board"></div>
  </div>
  <script>
    (function () {
      const SIZE = 4;
      let grid = emptyGrid();
      let currentScore = 0;

      function emptyGrid() {
        return Array.from({ length: SIZE }, () => Array(SIZE).fill(0));
      }

      function copyGrid(src) {
        return src.map(function (row) { return row.slice(); });
      }

      function boardsEqual(a, b) {
        for (let r = 0; r < SIZE; r++) {
          for (let c = 0; c < SIZE; c++) {
            if (a[r][c] !== b[r][c]) return false;
          }
        }
        return true;
      }

      function slideLine(line) {
        var tiles = [];
        for (var i = 0; i < line.length; i++) {
          if (line[i] !== 0) tiles.push(line[i]);
        }
        var merged = [];
        var gained = 0;
        var i = 0;
        while (i < tiles.length) {
          if (i + 1 < tiles.length && tiles[i] === tiles[i + 1]) {
            var val = tiles[i] * 2;
            merged.push(val);
            gained += val;
            i += 2;
          } else {
            merged.push(tiles[i]);
            i += 1;
          }
        }
        while (merged.length < SIZE) merged.push(0);
        return { line: merged, gained: gained };
      }

      function applyMove(dir) {
        var next = copyGrid(grid);
        var gained = 0;
        var r, c, result, col, rev;

        if (dir === 'left') {
          for (r = 0; r < SIZE; r++) {
            result = slideLine(next[r]);
            next[r] = result.line;
            gained += result.gained;
          }
        } else if (dir === 'right') {
          for (r = 0; r < SIZE; r++) {
            rev = next[r].slice().reverse();
            result = slideLine(rev);
            next[r] = result.line.reverse();
            gained += result.gained;
          }
        } else if (dir === 'up') {
          for (c = 0; c < SIZE; c++) {
            col = [];
            for (r = 0; r < SIZE; r++) col.push(next[r][c]);
            result = slideLine(col);
            for (r = 0; r < SIZE; r++) next[r][c] = result.line[r];
            gained += result.gained;
          }
        } else if (dir === 'down') {
          for (c = 0; c < SIZE; c++) {
            col = [];
            for (r = 0; r < SIZE; r++) col.push(next[r][c]);
            result = slideLine(col.reverse());
            rev = result.line.reverse();
            for (r = 0; r < SIZE; r++) next[r][c] = rev[r];
            gained += result.gained;
          }
        } else {
          return { changed: false, gained: 0, next: grid };
        }

        return { changed: !boardsEqual(grid, next), gained: gained, next: next };
      }

      function emptyCells() {
        var cells = [];
        for (var r = 0; r < SIZE; r++) {
          for (var c = 0; c < SIZE; c++) {
            if (grid[r][c] === 0) cells.push([r, c]);
          }
        }
        return cells;
      }

      function spawn() {
        var cells = emptyCells();
        if (!cells.length) return;
        var pick = cells[Math.floor(Math.random() * cells.length)];
        grid[pick[0]][pick[1]] = Math.random() < 0.9 ? 2 : 4;
      }

      function tileClass(v) {
        if (v === 0) return 'tile v0';
        if (v === 2) return 'tile v2';
        if (v === 4) return 'tile v4';
        if (v === 8) return 'tile v8';
        if (v === 16) return 'tile v16';
        if (v === 32) return 'tile v32';
        if (v === 64) return 'tile v64';
        if (v === 128) return 'tile v128';
        if (v === 256) return 'tile v256';
        if (v === 512) return 'tile v512';
        if (v === 1024) return 'tile v1024';
        if (v === 2048) return 'tile v2048';
        return 'tile vbig';
      }

      function render() {
        var boardEl = document.getElementById('board');
        boardEl.innerHTML = '';
        for (var r = 0; r < SIZE; r++) {
          for (var c = 0; c < SIZE; c++) {
            var v = grid[r][c];
            var cell = document.createElement('div');
            cell.className = tileClass(v);
            cell.textContent = v === 0 ? '' : String(v);
            boardEl.appendChild(cell);
          }
        }
        document.getElementById('score').textContent = String(currentScore);
      }

      function reset() {
        grid = emptyGrid();
        currentScore = 0;
        spawn();
        spawn();
        render();
      }

      function move(dir) {
        var result = applyMove(dir);
        if (!result.changed) {
          render();
          return false;
        }
        grid = result.next;
        currentScore += result.gained;
        spawn();
        render();
        return true;
      }

      function board() {
        return copyGrid(grid);
      }

      function setBoard(arr) {
        grid = copyGrid(arr);
        render();
      }

      function getScore() {
        return currentScore;
      }

      document.getElementById('reset').addEventListener('click', reset);

      document.addEventListener('keydown', function (e) {
        var map = {
          ArrowLeft: 'left',
          ArrowRight: 'right',
          ArrowUp: 'up',
          ArrowDown: 'down'
        };
        if (!map[e.key]) return;
        e.preventDefault();
        move(map[e.key]);
      });

      window.game = {
        size: SIZE,
        reset: reset,
        move: move,
        board: board,
        setBoard: setBoard,
        score: getScore
      };

      reset();
    })();
  </script>
</body>
</html>
